declare const BASE_URL: string;

// Declare global SimVar API
declare const SimVar: {
  GetSimVarValue(name: string, unit: string): number | boolean | string;
  SetSimVarValue(name: string, unit: string, value: number): void;
};

// Declare global MSFS ViewListener
declare function RegisterViewListener(name: string, callback?: () => void): unknown;

// Declare global Coherent API
declare const Coherent: {
  call(name: string, ...args: unknown[]): Promise<unknown>;
  trigger(name: string, ...args: unknown[]): void;
  on(name: string, callback: (...args: unknown[]) => void): { clear(): void };
};

type TabType = "map" | "profile" | "missions" | "create-mission" | "company" | "market" | "inventory" | "hangar" | "settings";
type ProfileSubTab = "apercu" | "licences" | "inventaire" | "transactions" | "messagerie" | "social";
type MissionsSubTab = "apercu" | "creation" | "historique";
type CompanySubTab = "apercu" | "personnel" | "messagerie" | "flotte" | "inventaire" | "usines" | "droits";

// V2.2: Hangar - Aircraft details from backend
interface AircraftDetails {
  id: string;
  registration: string | null;
  aircraft_type: string;
  aircraft_model: string;
  current_airport_ident: string | null;
  status: string;
  required_license: string | null;
  owner_type: string;  // V2.3: "company" | "player"
  // Persistent data
  fuel_gallons: number;
  fuel_capacity_gallons: number;
  cargo_kg: number;
  cargo_capacity_kg: number;
  passengers: number;
  passenger_capacity: number;
  // Systems status
  landing_gear: string;
  engine_status: string;
  propeller_status: string;
  electrical_status: string;
  pitot_status: string;
  avionics_status: string;
}

// Landing rating thresholds (in fpm, absolute value)
type LandingRating = "excellent" | "good" | "acceptable" | "hard" | null;

// User info type
interface UserInfo {
  id: number;
  username: string;
  email: string;
}

