  // V1.5: Toggle a unit preference and save
  private toggleUnit(unitType: "distance" | "weight" | "altitude" | "fuel" | "speed" | "temperature"): void {
    switch (unitType) {
      case "distance":
        this.unitDistance.set(this.unitDistance.get() === "nm" ? "km" : "nm");
        break;
      case "weight":
        this.unitWeight.set(this.unitWeight.get() === "kg" ? "lbs" : "kg");
        break;
      case "altitude":
        this.unitAltitude.set(this.unitAltitude.get() === "ft" ? "m" : "ft");
        break;
      case "fuel":
        this.unitFuel.set(this.unitFuel.get() === "gal" ? "L" : "gal");
        break;
      case "speed":
        this.unitSpeed.set(this.unitSpeed.get() === "kts" ? "kmh" : "kts");
        break;
      case "temperature":
        this.unitTemperature.set(this.unitTemperature.get() === "C" ? "F" : "C");
        break;
    }
    this.saveUnitPreferences();
  }

