      if (emailEl) emailEl.value = this.savedEmail || "";
      if (passwordEl) passwordEl.value = "";
      this.loginError.set(null);

      // Add keyboard event listeners to stop propagation to simulator
      // This prevents simulator shortcuts from triggering while typing
