  private updateMapPosition(): void {
    if (!this.olMap || !this.aircraftFeature) return;

    const lat = this.latitude.get();
    const lon = this.longitude.get();
    const heading = this.heading.get();

    if (lat === 0 && lon === 0) return;

    try {
      // Update aircraft position
      const coords = fromLonLat([lon, lat]);
      this.aircraftFeature.getGeometry()?.setCoordinates(coords);

      // Update aircraft rotation based on heading
      const aircraftSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24">
        <path fill="#3b82f6" stroke="#ffffff" stroke-width="1" d="M12 2L8 10H4L6 12L4 14H8L12 22L16 14H20L18 12L20 10H16L12 2Z"/>
      </svg>`;
      const aircraftIconUrl = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(aircraftSvg);

      this.aircraftFeature.setStyle(
        new Style({
          image: new Icon({
            src: aircraftIconUrl,
            scale: 1,
            rotation: (heading * Math.PI) / 180,
            rotateWithView: false,
          }),
        })
      );

      // Optionally center the map on the aircraft (can be toggled)
      // this.olMap.getView().setCenter(coords);
    } catch (error) {
      console.error("[CarrierPlus] Error updating map position:", error);
    }
  }

  private centerMapOnAircraft(): void {
    if (!this.olMap) return;

    const lat = this.latitude.get();
    const lon = this.longitude.get();

    if (lat === 0 && lon === 0) return;

    this.olMap.getView().animate({
      center: fromLonLat([lon, lat]),
      duration: 500,
    });
  }

  private async searchAirportByIcao(): Promise<void> {
    const inputEl = this.icaoSearchInputRef.getOrDefault();
    if (!inputEl) return;

    const icao = inputEl.value.trim().toUpperCase();
    if (!icao || icao.length < 2) {
      this.icaoSearchError.set("Entrez un code ICAO (min 2 caracteres)");
      return;
    }

    this.icaoSearchStatus.set("loading");
    this.icaoSearchError.set(null);

    try {
      // Search for airport by ICAO code
      const response = await fetch(
        `http://localhost:8000/api/world/airports?ident=${icao}&limit=1`,
        { method: "GET", headers: { "Accept": "application/json" } }
      );

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();
      const airports = data.airports || data || [];

      if (airports.length === 0) {
        this.icaoSearchError.set(`Aeroport "${icao}" non trouve`);
        this.icaoSearchStatus.set("error");
        return;
      }

      const airport = airports[0];
      const airportLat = airport.latitude_deg || airport.lat || 0;
      const airportLon = airport.longitude_deg || airport.lon || 0;

      if (airportLat === 0 && airportLon === 0) {
        this.icaoSearchError.set(`Coordonnees invalides pour "${icao}"`);
        this.icaoSearchStatus.set("error");
        return;
      }

      // Center map on the airport
      if (this.olMap) {
        this.olMap.getView().animate({
          center: fromLonLat([airportLon, airportLat]),
          zoom: 12,
          duration: 800,
        });
      }

      console.log(`[CarrierPlus] Centered on ${icao}: ${airport.name || ""} (${airportLat}, ${airportLon})`);
      this.icaoSearchStatus.set("success");

      // Clear input after successful search
      inputEl.value = "";

    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      console.error("[CarrierPlus] ICAO search failed:", errorMsg);
      this.icaoSearchError.set("Erreur de recherche");
      this.icaoSearchStatus.set("error");
    }
  }

  private toggleLargeAirports(): void {
    const newState = !this.showLargeAirports.get();
    this.showLargeAirports.set(newState);

    // Ensure layer is visible
    if (this.airportsLayer && newState) {
      this.airportsLayer.setVisible(true);
    }

    // Fetch airports for current view if turning on and no airports loaded yet
    if (newState && this.airportsSource && this.airportsSource.getFeatures().length === 0) {
      void this.fetchAirportsForMap();
    } else {
      this.filterAirportsOnMap();
    }

    // Hide layer if all airport types are off
    this.updateAirportsLayerVisibility();
  }

